mapper.select:
WITH candidates AS (
    SELECT id, embedding_id, conversation_history_id, user_id, session_id,
           symbol, content, embedding, metadata, created_at,
           1 - (embedding <=> CAST(#{vec} AS vector)) AS semantic_score
    FROM public.conversation_episode_embeddings
    WHERE user_id = #{userId}

        AND symbol = #{symbol}

    ORDER BY embedding <=> CAST(#{vec} AS vector)
    LIMIT #{candidateLimit}
)
SELECT id, embedding_id, conversation_history_id, user_id, session_id,
       symbol, content, embedding, metadata, created_at,
       semantic_score * #{semanticWeight}
       + (
           1.0 / (
               1.0
               + GREATEST(EXTRACT(EPOCH FROM (NOW() - created_at)) / 86400.0, 0)
                 / #{recencyHalfLifeDays}
           )
       ) * #{recencyWeight} AS score
FROM candidates
WHERE semantic_score >= #{minSimilarity}
ORDER BY score DESC, created_at DESC
LIMIT #{topK}

